package io.github.astelev.around_planet.space;
import org.junit.jupiter.api.Test;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
class RendezvousMathTest {
    private SpaceTrajectory line(SpaceVector p,SpaceVector v){return new SpaceTrajectory("test",0,new SpaceState(p,v),0);}
    @Test void relativeDirectionsDistinguishTargetFromRelativeVelocity(){var a=new SpaceState(new SpaceVector(100,0,0),new SpaceVector(0,15,0));var b=new SpaceState(new SpaceVector(110,0,0),new SpaceVector(0,10,0));assertEquals(new SpaceVector(1,0,0),RendezvousMath.direction(OrbitalAttitude.Mode.TARGET,a,b).orElseThrow());assertEquals(new SpaceVector(0,1,0),RendezvousMath.direction(OrbitalAttitude.Mode.RELATIVE_PROGRADE,a,b).orElseThrow());assertEquals(new SpaceVector(0,-1,0),RendezvousMath.direction(OrbitalAttitude.Mode.RELATIVE_RETROGRADE,a,b).orElseThrow());assertTrue(RendezvousMath.direction(OrbitalAttitude.Mode.TARGET,a,a).isEmpty());assertTrue(RendezvousMath.direction(OrbitalAttitude.Mode.RELATIVE_PROGRADE,a,a).isEmpty());}
    @Test void timeMinimizationFindsLinearMissDistanceAndRelativeSpeed(){var a=line(new SpaceVector(30000,0,0),new SpaceVector(10,0,0));var b=line(new SpaceVector(30100,30,0),SpaceVector.ZERO);var p=RendezvousMath.predict(a,null,b,0,20000,2000);var hit=p.approaches().getFirst();assertEquals(200,hit.tick(),1);assertEquals(30,hit.distance(),.01);assertEquals(10,hit.speed(),1e-8);}
    @Test void forecastUsesPlannedBurnRatherThanExecutingIt(){var a=line(new SpaceVector(30000,0,0),new SpaceVector(10,0,0));var b=line(new SpaceVector(30100,30,0),SpaceVector.ZERO);var node=new ManeuverNode(UUID.randomUUID(),100,0,-6,0);var preview=ManeuverPreview.create(a,0,List.of(node),20000,2000);var p=RendezvousMath.predict(a,preview,b,0,20000,2000);assertTrue(p.approaches().getFirst().distance()<.5);assertEquals(new SpaceVector(10,0,0),a.initial().velocity());assertEquals(30,RendezvousMath.predict(a,null,b,0,20000,2000).approaches().getFirst().distance(),.01);}
    @Test void mutualNodesBelongToBothPlanesAndAscendingCrossingHasPositiveSign(){double mu=4e9,r=30000,v=Math.sqrt(mu/r),i=.3;var own=new SpaceState(new SpaceVector(r,0,0),new SpaceVector(0,v,0));var target=new SpaceState(new SpaceVector(r,0,0),new SpaceVector(0,v*Math.cos(i),v*Math.sin(i)));var planes=RendezvousMath.planes(own,target,mu);assertEquals(Math.toDegrees(i),planes.inclination(),1e-8);var n=target.position().cross(target.velocity());assertEquals(0,n.dot(planes.ascending()),1e-5);assertEquals(0,planes.ascending().z(),1e-8);assertTrue(own.position().cross(own.velocity()).cross(planes.ascending()).dot(n)>0);assertEquals(r,planes.ascending().length(),1e-6);}
    @Test void coincidentCircularOrbitsHaveNoArbitraryRepeatedClosestPoints(){double mu=4e9,r=30000;var a=new SpaceTrajectory("test",0,new SpaceState(new SpaceVector(r,0,0),new SpaceVector(0,Math.sqrt(mu/r),0)),mu);assertTrue(RendezvousMath.predict(a,null,a,0,20000,2000).approaches().isEmpty());}
    @Test void repeatedEllipticalPassesAgreeWithIndependentDenseTimeSampling(){double mu=4e9,r=30000,peri=24000,a=42000;var own=new SpaceTrajectory("test",0,new SpaceState(new SpaceVector(r,0,0),new SpaceVector(0,Math.sqrt(mu/r),0)),mu);var target=new SpaceTrajectory("test",0,new SpaceState(new SpaceVector(0,peri,0),new SpaceVector(-Math.sqrt(mu*(2/peri-1/a)),0,0)),mu);var result=RendezvousMath.predict(own,null,target,0,20000,1000);assertTrue(result.approaches().size()>=2);double oracle=Double.POSITIVE_INFINITY,previous=own.at(0).position().subtract(target.at(0).position()).length(),middle=own.at(10).position().subtract(target.at(10).position()).length();for(long tick=20;tick<=result.until();tick+=10){double next=own.at(tick).position().subtract(target.at(tick).position()).length();if(middle<previous&&middle<=next)oracle=Math.min(oracle,middle);previous=middle;middle=next;}double best=result.approaches().stream().mapToDouble(RendezvousMath.Approach::distance).min().orElseThrow();assertTrue(best<=oracle+1,"Missed a closer passage between orbit samples");assertEquals(best,result.approaches().getFirst().distance(),1e-6,"Map should prioritize the tightest encounter rather than the first distant pass");}
    @Test void matchingVelocityAtArrivalReportsTheFirstContactRatherThanALaterFlatMinimum(){var own=line(new SpaceVector(30000,0,0),new SpaceVector(10,0,0));var target=line(new SpaceVector(30100,0,0),SpaceVector.ZERO);var node=new ManeuverNode(UUID.randomUUID(),200,-10,0,0);var plan=ManeuverPreview.create(own,0,List.of(node),20000,1000);var hit=RendezvousMath.predict(own,plan,target,0,20000,1000).approaches().getFirst();assertEquals(200,hit.tick(),1);assertEquals(0,hit.distance(),1e-6);assertEquals(0,hit.speed(),1e-6);}
}
